package dev.cazajefes;
import org.junit.Test;
import static org.junit.Assert.*;
import org.bukkit.entity.*;
public class ArmadilloAndMinionTest {
 @Test public void armadilloOpensWithAiAndDoesNotRepeatRollOutDuringTransition(){var state=new java.util.concurrent.atomic.AtomicReference<>(Armadillo.State.SCARED);int[] rolls={0};boolean[] ai={false};Armadillo entity=(Armadillo)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{Armadillo.class},(object,method,args)->{switch(method.getName()){case "getState":return state.get();case "setAI":ai[0]=(Boolean)args[0];return null;case "setMemory":return null;case "rollOut":rolls[0]++;state.set(Armadillo.State.UNROLLING);return null;default:throw new UnsupportedOperationException(method.getName());}});assertFalse(ArmadilloMotion.open(entity));assertTrue(ai[0]);assertEquals(1,rolls[0]);assertFalse(ArmadilloMotion.open(entity));assertEquals(1,rolls[0]);state.set(Armadillo.State.IDLE);assertTrue(ArmadilloMotion.open(entity));assertFalse(ai[0]);assertEquals(1,rolls[0]);}
 @Test public void unrollingAnimationIsNotRestartedAndIdleDoesNotRollAgain(){assertTrue(ArmadilloMotion.startUnroll(Armadillo.State.SCARED));assertTrue(ArmadilloMotion.startUnroll(Armadillo.State.ROLLING));assertFalse(ArmadilloMotion.startUnroll(Armadillo.State.UNROLLING));assertFalse(ArmadilloMotion.startUnroll(Armadillo.State.IDLE));}
 @Test public void meleeApproachesAndArchersKeepSixToTwelveBlocks(){assertEquals(MinionTactics.Move.APPROACH,MinionTactics.move(false,true,3));assertEquals(MinionTactics.Move.RETREAT,MinionTactics.move(true,true,4));assertEquals(MinionTactics.Move.STRAFE,MinionTactics.move(true,true,9));assertEquals(MinionTactics.Move.APPROACH,MinionTactics.move(true,true,15));assertEquals(MinionTactics.Move.APPROACH,MinionTactics.move(true,false,9));assertTrue(MinionTactics.ranged(EntityType.SKELETON));assertTrue(MinionTactics.ranged(EntityType.EVOKER));assertFalse(MinionTactics.ranged(EntityType.ZOMBIE));}
 @Test public void sphereCoversTheBodyWithoutExceedingExistingBudget(){var points=BurstVisuals.microSphere(2,4);assertEquals(24,points.size());assertEquals(384,points.size()*BurstVisuals.star(.07).size()*4);for(var p:points)assertEquals(1,(p.x()*p.x()+p.z()*p.z())/4+p.y()*p.y()/16,.000001);assertTrue(points.stream().anyMatch(p->p.y()>3.5));assertTrue(points.stream().anyMatch(p->p.y()<-3.5));}
 @Test public void namesHaveOneOriginalSuffixAndKeepCanonicalIds(){assertEquals("Ímpetu del Relámpago (Haste)",RareDefinitions.get("haste").title());assertEquals("Corazón Indómito (Hardy)",RareDefinitions.get("hardy").title());assertEquals("Haste",RareNames.original("haste"));assertEquals("Corazón Indómito",RareNames.bare(RareDefinitions.get("hardy").title()));assertEquals("Furia (Strength)",RareNames.title("strength","Furia (Strength)"));}
}
